      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00301",
        "explanation": "Later reasoning appropriately deferred long-acting insulin decisions to acute clinicians after reassessment.",
        "quote": "睡前长效一定等急诊或值班内分泌医生复测后口头确认再打"
      }
    ],
    "continuity_memory_focus": [
      {
